import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [queues, setQueues] = useState([]);
  const [form, setForm] = useState({
    patientName: "",
    doctor: "",
    department: "",
    date: ""
  });

  const fetchQueues = async () => {
    const res = await fetch("http://localhost:5000/api/queue/all");
    const data = await res.json();
    setQueues(data);
  };

  useEffect(() => {
    fetchQueues();

    socket.on("queueUpdated", fetchQueues);

    socket.on("notification", (msg) => {
      console.log("NOTIFICATION:", msg);
    });

    return () => socket.off();
  }, []);

  const bookOP = async () => {
    await fetch("http://localhost:5000/api/queue/book", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form)
    });

    setForm({
      patientName: "",
      doctor: "",
      department: "",
      date: ""
    });
  };

  const joinQueue = async (id) => {
    await fetch(`http://localhost:5000/api/queue/join/${id}`, {
      method: "PUT"
    });
  };

  return (
    <div style={{ padding: 20 }}>

      <h2>👤 Patient Panel</h2>

      <input placeholder="Name"
        value={form.patientName}
        onChange={(e) => setForm({ ...form, patientName: e.target.value })} />

      <input placeholder="Doctor"
        value={form.doctor}
        onChange={(e) => setForm({ ...form, doctor: e.target.value })} />

      <input placeholder="Department"
        value={form.department}
        onChange={(e) => setForm({ ...form, department: e.target.value })} />

      <input type="date"
        value={form.date}
        onChange={(e) => setForm({ ...form, date: e.target.value })} />

      <button onClick={bookOP}>Book OP</button>

      <hr />

      <h3>Your OP</h3>

      {queues.map((q) => (
        <div key={q._id}>
          <p>Token: {q.tokenNumber}</p>
          <p>Status: {q.status}</p>

          {q.status === "Confirmed" && (
            <button onClick={() => joinQueue(q._id)}>
              Join Queue
            </button>
          )}
        </div>
      ))}

    </div>
  );
}

export default PatientDashboard;
